            aOrbiterG = (((aWandererC + RotL64(aIngress, 51U)) + RotL64(aCarry, 11U)) + 0x4D8E1AABF65CF579ULL) + aTwistOrbiterAssignSaltE[(((31U - aIndex) + 15U)) & S_SALT1];
            aOrbiterB = ((aWandererA + RotL64(aScatter, 43U)) + RotL64(aCarry, 27U)) + 0x23989AD71C5575B4ULL;
