            aOrbiterC = ((aWandererH + RotL64(aCross, 21U)) + RotL64(aCarry, 35U)) + 0x5694DC5DA7DB86CFULL;
            aOrbiterJ = (((aWandererF + RotL64(aScatter, 60U)) + RotL64(aCarry, 3U)) + 0x6409B0CC65D3D854ULL) + aTwistOrbiterAssignSaltF[((aIndex + 25U)) & S_SALT1];
            aOrbiterK = (((aWandererE + RotL64(aPrevious, 3U)) + RotL64(aCarry, 23U)) + 0xBDF042E5BF1D3D0BULL) + aTwistOrbiterAssignSaltC[(((31U - aIndex) + 19U)) & S_SALT1];
            aOrbiterF = (aWandererK + RotL64(aScatter, 41U)) + 0xEDA4564D1333668EULL;
            aOrbiterH = (aWandererJ + RotL64(aPrevious, 51U)) + 0x2C6BB3F0F8216891ULL;
            aOrbiterI = (aWandererI + RotL64(aIngress, 29U)) + 0xC3D20A17F611A2CDULL;
            //
            aOrbiterB = (aOrbiterB + aOrbiterC) + 0x767558197314811FULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterB) ^ 0x48CB5018DDD4CC44ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0xAC4A78D25209DF0FULL), 13U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterF) + 0x126199765412326AULL;
