            aOrbiterF = (aOrbiterF + aOrbiterH) + 0xBAB29F349856AF81ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterF) ^ 0x89B416DB12E3CFC8ULL;
            aOrbiterC = RotL64((aOrbiterC * 0x4E0A532B782AAC13ULL), 21U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterJ) + 0x18AA6866C044C2B0ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterI) ^ 0x575B153930527C59ULL;
            aOrbiterF = RotL64((aOrbiterF * 0xC6B3F513BCDAFC15ULL), 29U);
            //
            aOrbiterC = ((aOrbiterC + aOrbiterI) + 0x378A6C18AF92A2ABULL) + aTwistOrbiterUpdateSaltC[((aIndex + 8U)) & S_SALT1];
            aOrbiterK = ((aOrbiterK ^ aOrbiterC) ^ 0x3EADA04E36124F65ULL) ^ aTwistOrbiterUpdateSaltD[((aIndex + 15U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0x12746BA30BEEFE37ULL), 51U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterB) + 0xF6D946832C0863F3ULL) + aTwistOrbiterUpdateSaltA[((aIndex + 13U)) & S_SALT1];
            aOrbiterI = ((aOrbiterI ^ aOrbiterH) ^ 0x40E77BC721CF23A9ULL) ^ aTwistOrbiterUpdateSaltE[(((31U - aIndex) + 6U)) & S_SALT1];
            aOrbiterI = RotL64((aOrbiterI * 0x362038A47E5E7919ULL), 57U);
