            aPrevious = aIngress;
            //
            aIngress = (RotL64(aFireLaneD[((aIndex + 13833U)) & S_BLOCK1], 11U) ^ RotL64(aEarthLaneA[((aIndex + 11885U)) & S_BLOCK1], 21U));
            aIngress ^= RotL64(aFireLaneB[((S_BLOCK1 - aIndex + 14660U)) & S_BLOCK1], 38U);
