            //
            aCross = (RotL64(aFireLaneC[((S_BLOCK1 - aIndex + 15582U)) & S_BLOCK1], 24U) ^ RotL64(aEarthLaneC[((S_BLOCK1 - aIndex + 13993U)) & S_BLOCK1], 51U));
