            aScatter = (RotL64(aPrevious, 5U) + RotL64(aCross, 21U)) ^ (RotL64(aCarry, 36U) + RotL64(aIngress, 53U));
            aScatter = TwistMix64::DiffuseB(aScatter);
            //
