            aCross = (RotL64(aFuseLaneA[((S_BLOCK1 - aIndex + 24262U)) & S_BLOCK1], 43U) ^ RotL64(aWaterLaneB[((S_BLOCK1 - aIndex + 18027U)) & S_BLOCK1], 52U));
