            //
            aOrbiterD = ((aWandererE + RotL64(aCross, 11U)) + RotL64(aCarry, 53U)) + 0xE1E6A3C8C06A4502ULL;
            aOrbiterA = (((aWandererB + RotL64(aIngress, 50U)) + RotL64(aCarry, 5U)) + 0xF3C07C293DE7062AULL) + aTwistOrbiterAssignSaltF[(((31U - aIndex) + 6U)) & S_SALT1];
            aOrbiterE = ((aWandererG + RotL64(aScatter, 39U)) + RotL64(aCarry, 41U)) + 0x4108E2CC8680DA96ULL;
            aOrbiterK = (aWandererA + RotL64(aPrevious, 3U)) + 0xDE6D65B11CB4176EULL;
            aOrbiterB = (aWandererC + RotL64(aIngress, 29U)) + 0xE6D113DB060C83DDULL;
            aOrbiterH = (aWandererJ + RotL64(aCross, 57U)) + 0xE5D86F74530C3108ULL;
            aOrbiterG = ((aWandererI + RotL64(aPrevious, 23U)) + 0x7EDC958771ED6EBEULL) + aTwistOrbiterAssignSaltB[((aIndex + 3U)) & S_SALT1];
            //
            aOrbiterD = ((aOrbiterD + aOrbiterA) + 0x6F138433F1BE812BULL) + aTwistOrbiterUpdateSaltC[((aIndex + 26U)) & S_SALT1];
