            aOrbiterH = RotL64((aOrbiterH * 0xCF1A1E35DC49E80DULL), 21U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterG) + 0x63D7E9EC39B3A764ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterH) ^ 0xEB5ECA0B0F76AEDBULL;
            aOrbiterD = RotL64((aOrbiterD * 0x2171374F82A72BC5ULL), 47U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterH) + 0x6E975BBBC873DF19ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterB) ^ 0x4F634D389FB5B9FCULL;
            aOrbiterG = RotL64((aOrbiterG * 0x43FA4A5CBD90377BULL), 27U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterE) + 0x7567F2F78739A420ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterA) ^ 0x8D30AAE3BB81B018ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x4E6B234B489A7891ULL), 37U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterD) + 0x507672D88D14AF03ULL) + aTwistOrbiterUpdateSaltD[(((31U - aIndex) + 10U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterG) ^ 0x7C8DA0213A5DEED7ULL;
            aOrbiterA = RotL64((aOrbiterA * 0xEBD34147853033E3ULL), 11U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterK) + 0x2AB613D6BE0EE043ULL) + aTwistOrbiterUpdateSaltF[(((31U - aIndex) + 23U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterE) ^ 0xF39F0E4119D64E34ULL;
