            aOrbiterE = (((aWandererI + RotL64(aPrevious, 47U)) + RotL64(aCarry, 37U)) + 0xDC0F7ECFC23106D3ULL) + aTwistOrbiterAssignSaltE[((aIndex + 29U)) & S_SALT1];
