            aOrbiterJ = (aWandererA + RotL64(aScatter, 41U)) + 0xE0C867AAE786EDF5ULL;
            aOrbiterC = ((aWandererB + RotL64(aIngress, 13U)) + RotL64(aCarry, 23U)) + 0xE624C0984DA86443ULL;
            aOrbiterB = (aWandererH + RotL64(aPrevious, 23U)) + 0x535CF02FA917F491ULL;
            aOrbiterH = (aWandererJ + RotL64(aScatter, 57U)) + 0xDD4249DD56EF4D30ULL;
            aOrbiterI = ((aWandererD + RotL64(aIngress, 3U)) + 0x49F0FED659677F42ULL) + aTwistOrbiterAssignSaltC[(((31U - aIndex) + 11U)) & S_SALT1];
