            aOrbiterB = (aOrbiterB + aOrbiterE) + 0x119812905A9A26E1ULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterB) ^ 0xBE3F98126F98786CULL) ^ aTwistOrbiterUpdateSaltA[(((31U - aIndex) + 7U)) & S_SALT1];
