            aWandererB = aWandererB ^ (((RotL64(aCross, 41U) + RotL64(aOrbiterC, 27U)) + aOrbiterB) + aTwistWandererUpdateSaltD[(((31U - aIndex) + 12U)) & S_SALT1]);
