            aOrbiterB = RotL64((aOrbiterB * 0x92D80903563515BDULL), 27U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterB) + 0x3585667B7BA0911BULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterK) ^ 0xE96BF37B1782BF80ULL) ^ aTwistOrbiterUpdateSaltD[((aIndex + 3U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0xF76B636703590DC5ULL), 51U);
