            aCross = (RotL64(aSoilLaneC[((S_BLOCK1 - aIndex + 929U)) & S_BLOCK1], 3U) ^ RotL64(aSoilLaneD[((S_BLOCK1 - aIndex + 1298U)) & S_BLOCK1], 18U));
