            //
            aOrbiterG = (aWandererF + RotL64(aScatter, 27U)) + 0xFD1DAB2728C879C2ULL;
            aOrbiterE = (((aWandererK + RotL64(aCross, 58U)) + RotL64(aCarry, 39U)) + 0xD992A14A910BD6B0ULL) + aTwistOrbiterAssignSaltD[(((31U - aIndex) + 14U)) & S_SALT1];
