            aOrbiterG = (((aWandererK + RotL64(aIngress, 43U)) + RotL64(aCarry, 27U)) + 0x9051DF83E3E62792ULL) + aTwistOrbiterAssignSaltE[((aIndex + 5U)) & S_SALT1];
            aOrbiterB = ((aWandererD + RotL64(aScatter, 35U)) + 0x5D3B19C1940BD2E9ULL) + aTwistOrbiterAssignSaltF[(((31U - aIndex) + 15U)) & S_SALT1];
            aOrbiterA = ((aWandererF + RotL64(aPrevious, 29U)) + RotL64(aCarry, 11U)) + 0x708C184748583068ULL;
            aOrbiterJ = ((aWandererI + RotL64(aCross, 12U)) + RotL64(aCarry, 41U)) + 0xDAFCD09AC0CBD6BBULL;
            aOrbiterE = (aWandererB + RotL64(aPrevious, 3U)) + 0xAB47060CC64CE140ULL;
            aOrbiterI = (aWandererG + RotL64(aIngress, 53U)) + 0x3F52C3075E51C493ULL;
            aOrbiterC = (aWandererA + RotL64(aCross, 19U)) + 0x74E69DC956D578BDULL;
            //
            aOrbiterG = (aOrbiterG + aOrbiterB) + 0xD5777898B111AB3DULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterG) ^ 0x09BBA3739C86790BULL;
            aOrbiterA = RotL64((aOrbiterA * 0x6BD53DC4D29ACEA7ULL), 43U);
