            aCross ^= (RotL64(aEarthLaneA[((S_BLOCK1 - aIndex + 19154U)) & S_BLOCK1], 47U) ^ RotL64(aIceLaneD[((aIndex + 20017U)) & S_BLOCK1], 39U));
            aCross = TwistMix64::DiffuseC(aCross);
            //
            aScatter = (RotL64(aPrevious, 39U) + RotL64(aCross, 3U)) + (RotL64(aIngress, 51U) ^ RotL64(aCarry, 22U));
            aScatter = TwistMix64::DiffuseC(aScatter);
            //
            aOrbiterI = (aWandererD + RotL64(aIngress, 29U)) + 0x03F6BB071FA797A6ULL;
            aOrbiterD = ((aWandererH + RotL64(aPrevious, 21U)) + RotL64(aCarry, 5U)) + 0x5B6D2FD073C30CE2ULL;
            aOrbiterC = ((aWandererB + RotL64(aCross, 37U)) + 0x86866A069ADAB5CEULL) + aKeyRotateOrbiterAssignSaltA[(((31U - aIndex) + 19U)) & S_SALT1];
            aOrbiterK = ((aWandererG + RotL64(aScatter, 5U)) + RotL64(aCarry, 51U)) + 0x8F32B18B288BE8CEULL;
            aOrbiterF = ((aWandererK + RotL64(aIngress, 44U)) + 0x1088168489F17E38ULL) + aKeyRotateOrbiterAssignSaltB[((aIndex + 20U)) & S_SALT1];
            aOrbiterB = ((aWandererF + RotL64(aCross, 57U)) + RotL64(aCarry, 23U)) + 0x39B848CD164286F4ULL;
            aOrbiterG = (aWandererA + RotL64(aPrevious, 51U)) + 0xB2D562B5CEC38BE2ULL;
            //
            aOrbiterI = (aOrbiterI + aOrbiterD) + 0xF9F5E943C2E2D2C2ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterI) ^ 0x204A0AF311F60B75ULL;
            aOrbiterC = RotL64((aOrbiterC * 0x341DAD0E6D6AF2FBULL), 3U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterF) + 0x5ABCC43166C249ECULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterK) ^ 0xACB3776BCE2B75BAULL) ^ aKeyRotateOrbiterUpdateSaltC[(((31U - aIndex) + 15U)) & S_SALT1];
            aOrbiterI = RotL64((aOrbiterI * 0xCF8CD67C4721C2DFULL), 51U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterC) + 0x528FD75D55F5D9D9ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterD) ^ 0x64BF625AD649B213ULL;
            aOrbiterB = RotL64((aOrbiterB * 0x1E31C8D84D67D145ULL), 29U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterK) + 0x39E81C62416E0A12ULL) + aKeyRotateOrbiterUpdateSaltF[(((31U - aIndex) + 24U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterG) ^ 0x5D69A1AB9CEB3798ULL;
            aOrbiterF = RotL64((aOrbiterF * 0xDC5437A252A56165ULL), 13U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterG) + 0x8F2D622CA1EE5391ULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterB) ^ 0xFEEAC05B1DA58E6CULL) ^ aKeyRotateOrbiterUpdateSaltB[(((31U - aIndex) + 9U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0xA9A5219F7F52D723ULL), 21U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterB) + 0x90E89A7784E9562FULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterC) ^ 0x45795DCDD6FB987AULL;
            aOrbiterG = RotL64((aOrbiterG * 0xD0B37E3F69E376C1ULL), 35U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterI) + 0x8FD2BB4E5A711240ULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterF) ^ 0x80E6A0BD1F2E1E3CULL) ^ aKeyRotateOrbiterUpdateSaltD[((aIndex + 3U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0xD98AFE539F0C06A3ULL), 41U);
            //
            aIngress = aOrbiterG ^ RotL64(aOrbiterK, 37U);
            aIngress = aIngress + (aOrbiterC ^ RotL64(aOrbiterF, 11U));
            aIngress = aIngress + (aOrbiterI ^ RotL64(aOrbiterD, 30U));
            aIngress = aIngress + RotL64(aOrbiterB, 43U);
            aIngress = TwistMix64::DiffuseC((aIngress + aScatter));
            //
            aWandererB = aWandererB ^ ((RotL64(aIngress, 57U) + aOrbiterF) + RotL64(aOrbiterI, 39U));
            aWandererA = aWandererA + ((((RotL64(aPrevious, 27U) + aOrbiterG) + RotL64(aOrbiterK, 19U)) + RotL64(aCarry, 5U)) + aKeyRotateWandererUpdateSaltD[((aIndex + 23U)) & S_SALT1]);
            aWandererF = aWandererF ^ ((RotL64(aScatter, 6U) + aOrbiterC) + RotL64(aOrbiterB, 46U));
            aWandererG = aWandererG + ((RotL64(aCross, 35U) + aOrbiterB) + RotL64(aOrbiterD, 3U));
            aWandererK = aWandererK ^ ((RotL64(aPrevious, 41U) + RotL64(aOrbiterC, 53U)) + aOrbiterG);
            aWandererD = aWandererD + (((RotL64(aCross, 19U) + RotL64(aOrbiterI, 27U)) + aOrbiterK) + RotL64(aCarry, 35U));
            aWandererH = aWandererH ^ (((RotL64(aIngress, 51U) + RotL64(aOrbiterK, 13U)) + aOrbiterB) + aKeyRotateWandererUpdateSaltC[((aIndex + 27U)) & S_SALT1]);
            //
            aCarry = aCarry + (RotL64(aWandererA, 53U) ^ aWandererG);
