            //
            aCross = (RotL64(aShadowLaneB[((S_BLOCK1 - aIndex + 30054U)) & S_BLOCK1], 11U) ^ RotL64(aFireLaneA[((S_BLOCK1 - aIndex + 29972U)) & S_BLOCK1], 53U));
