            //
            aScatter = (RotL64(aIngress, 51U) + RotL64(aCross, 21U)) ^ (RotL64(aPrevious, 34U) + RotL64(aCarry, 5U));
            aScatter = TwistMix64::DiffuseA(aScatter);
            //
            aOrbiterA = ((aWandererE + RotL64(aScatter, 43U)) + 0x4812D72D5B72ECF9ULL) + aKeyRotateOrbiterAssignSaltC[(((31U - aIndex) + 8U)) & S_SALT1];
            aOrbiterF = (aWandererH + RotL64(aCross, 29U)) + 0xB19ED1B1524B218AULL;
            aOrbiterK = ((aWandererC + RotL64(aIngress, 53U)) + RotL64(aCarry, 53U)) + 0x838C1DE358A6539AULL;
            aOrbiterC = ((aWandererK + RotL64(aPrevious, 37U)) + RotL64(aCarry, 39U)) + 0x4A6D9B228F8932D7ULL;
            aOrbiterI = (aWandererA + RotL64(aCross, 22U)) + 0xF8AB46797778EFE4ULL;
            aOrbiterH = ((aWandererI + RotL64(aScatter, 3U)) + RotL64(aCarry, 5U)) + 0xD562C7F55B77855CULL;
            aOrbiterD = ((aWandererJ + RotL64(aPrevious, 11U)) + 0x27351DE14531684AULL) + aKeyRotateOrbiterAssignSaltE[(((31U - aIndex) + 28U)) & S_SALT1];
