            aOrbiterA = ((aOrbiterA + aOrbiterF) + 0xE57416695D2F32DCULL) + aKeyRotateOrbiterUpdateSaltF[((aIndex + 27U)) & S_SALT1];
            aOrbiterK = ((aOrbiterK ^ aOrbiterA) ^ 0x5B8D06C55FC08FABULL) ^ aKeyRotateOrbiterUpdateSaltB[((aIndex + 13U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0x9B94F47C636D6A41ULL), 13U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterC) + 0xB8B9B1D4488FC61FULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterK) ^ 0x5E055244D471B471ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x14B25BD634FE5A99ULL), 41U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterD) + 0x2B829E6BC1FAE7B0ULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterH) ^ 0x1115175F2C9EE117ULL) ^ aKeyRotateOrbiterUpdateSaltD[((aIndex + 14U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0xA2BD7AC8548B1DBDULL), 53U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterK) + 0x35B1CDB51A33DBC8ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterF) ^ 0xB5FBF3AFC340F320ULL;
            aOrbiterC = RotL64((aOrbiterC * 0xC5C44F0AE665F9C3ULL), 47U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterH) + 0x67420FA135BE873CULL) + aKeyRotateOrbiterUpdateSaltE[((aIndex + 7U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterI) ^ 0xD47284436ED556F9ULL;
            aOrbiterD = RotL64((aOrbiterD * 0xE607039C94C45137ULL), 19U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterI) + 0x31215CBF8230C2ECULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterC) ^ 0xB686813840B9ED4EULL;
            aOrbiterH = RotL64((aOrbiterH * 0x5AFB9E881605ECC1ULL), 35U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterA) + 0xB4BC2227EBA306A7ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterD) ^ 0x9E8EC910630685F2ULL;
