            aOrbiterF = RotL64((aOrbiterF * 0xCAAD3970D6860873ULL), 41U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterD) + 0xDD09EEDC8963D2C0ULL) + aKeyRotateOrbiterUpdateSaltE[((aIndex + 19U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterG) ^ 0x55FC162495F24F29ULL;
            aOrbiterA = RotL64((aOrbiterA * 0xF50496978B4327B3ULL), 51U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterF) + 0x411B135F4CD54C38ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterB) ^ 0xA5A1788605124641ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x3E61D67868304FAFULL), 27U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterI) + 0xD0CC8162E0AAB4E5ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterF) ^ 0x38B7F7DF195C1128ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x5E241AF9F70EFCEBULL), 23U);
