            aWandererK = aWandererK + (((RotL64(aCross, 50U) + RotL64(aOrbiterD, 19U)) + aOrbiterB) + aKeyRotateWandererUpdateSaltE[((aIndex + 13U)) & S_SALT1]);
            aWandererB = aWandererB ^ ((RotL64(aScatter, 21U) + aOrbiterC) + RotL64(aOrbiterG, 43U));
            aWandererE = aWandererE + (((RotL64(aPrevious, 3U) + RotL64(aOrbiterC, 5U)) + aOrbiterJ) + aKeyRotateWandererUpdateSaltC[(((31U - aIndex) + 3U)) & S_SALT1]);
            aWandererH = aWandererH ^ ((RotL64(aCross, 27U) + aOrbiterF) + RotL64(aOrbiterH, 40U));
            //
            aCarry = aCarry + (RotL64(aWandererA, 14U) ^ aWandererD);
            aCarry = aCarry + (aWandererB ^ RotL64(aWandererC, 53U));
