            aOrbiterE = (aWandererC + RotL64(aPrevious, 37U)) + 0x50D46D838EFE27DCULL;
            aOrbiterB = (((aWandererI + RotL64(aScatter, 30U)) + RotL64(aCarry, 39U)) + 0x46566C0F9030DEFDULL) + aKeyRotateOrbiterAssignSaltC[(((31U - aIndex) + 29U)) & S_SALT1];
            aOrbiterG = (aWandererJ + RotL64(aCross, 35U)) + 0x90F41924FABA17F1ULL;
            aOrbiterD = (aWandererH + RotL64(aIngress, 19U)) + 0xBBE3D3472B61328EULL;
            aOrbiterI = (aWandererD + RotL64(aCross, 11U)) + 0x04446E4F0ABF3452ULL;
            aOrbiterF = ((aWandererF + RotL64(aIngress, 54U)) + RotL64(aCarry, 35U)) + 0xB4B21D1348B0DAABULL;
            aOrbiterA = ((aWandererA + RotL64(aPrevious, 5U)) + RotL64(aCarry, 51U)) + 0x17D1C3ED3D2FAD34ULL;
            aOrbiterH = ((aWandererG + RotL64(aScatter, 39U)) + 0x5095BF49D95C1A32ULL) + aKeyRotateOrbiterAssignSaltE[((aIndex + 15U)) & S_SALT1];
            aOrbiterJ = (aWandererK + RotL64(aPrevious, 3U)) + 0xC8ADD203A268AF40ULL;
