            aOrbiterG = RotL64((aOrbiterG * 0xD68A8D1D0FA17A7DULL), 11U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterE) + 0x9384CD350633F3C2ULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterD) ^ 0xF386DF38D4C3C0F2ULL) ^ aKeyRotateOrbiterUpdateSaltB[(((31U - aIndex) + 11U)) & S_SALT1];
            aOrbiterI = RotL64((aOrbiterI * 0x853D1DB79F6B1695ULL), 37U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterA) + 0x1C6C431114608C76ULL) + aKeyRotateOrbiterUpdateSaltC[(((31U - aIndex) + 26U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterF) ^ 0xF25A128AA98BADADULL;
            aOrbiterD = RotL64((aOrbiterD * 0x8CED9DF4CB5AE8B3ULL), 13U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterJ) + 0xF32DC3D873584845ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterH) ^ 0x673ABCAB903BA57DULL;
            aOrbiterA = RotL64((aOrbiterA * 0xED615D7468DF8F33ULL), 35U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterG) + 0x6C5CAD255C4FCB01ULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterI) ^ 0x43AC0D23C2CC0BADULL) ^ aKeyRotateOrbiterUpdateSaltE[((aIndex + 9U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x861A8C411739944FULL), 5U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterK) + 0x55B2FE263F2349C6ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterG) ^ 0x4394F643D7C811E6ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0xB12907D5F17E71AFULL), 19U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterC) + 0x1752BC7BE91FCA72ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterA) ^ 0xAE97A11B2E3D1E68ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x71465CCC17642925ULL), 51U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterI) + 0x169287919A0C893DULL;
