            aOrbiterK = (aOrbiterK + aOrbiterH) + 0xC7154AB95A288708ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterK) ^ 0x6A76577250D06F9EULL;
            aOrbiterF = RotL64((aOrbiterF * 0xD2C3F2F658D54C3DULL), 3U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterF) + 0x997D0F87AF58741AULL;
