            aOrbiterC = (aOrbiterC + aOrbiterD) + 0x78F181E95C6DC162ULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterC) ^ 0xB383AEC0E28BB910ULL) ^ aKeyRotateOrbiterUpdateSaltA[(((31U - aIndex) + 19U)) & S_SALT1];
