            //
            aOrbiterH = (((aWandererE + RotL64(aPrevious, 11U)) + RotL64(aCarry, 23U)) + 0xB9423E6EA5229692ULL) + aKeyRotateOrbiterAssignSaltD[((aIndex + 18U)) & S_SALT1];
            aOrbiterA = (aWandererG + RotL64(aScatter, 3U)) + 0x41E0D1AF34F5B9EBULL;
            aOrbiterB = ((aWandererC + RotL64(aIngress, 23U)) + 0x86C38F8F6A97C844ULL) + aKeyRotateOrbiterAssignSaltC[(((31U - aIndex) + 22U)) & S_SALT1];
