            aOrbiterC = ((aWandererI + RotL64(aScatter, 60U)) + RotL64(aCarry, 57U)) + 0xB9D49D96EB9515E9ULL;
            aOrbiterE = ((aWandererD + RotL64(aIngress, 41U)) + RotL64(aCarry, 39U)) + 0xC288B09C3BE68E56ULL;
