            //
            aOrbiterH = (aOrbiterH + aOrbiterA) + 0x1B9625F9ED706AFEULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterH) ^ 0xBF5A4C3F74CA7F1AULL;
            aOrbiterB = RotL64((aOrbiterB * 0xCCA6D424D9B1A8EFULL), 5U);
            //
