            aWandererI = aWandererI ^ ((RotL64(aPrevious, 43U) + RotL64(aOrbiterC, 27U)) + aOrbiterA);
            //
            aCarry = aCarry + (RotL64(aWandererC, 54U) ^ aWandererK);
