            aOrbiterF = RotL64((aOrbiterF * 0xAB7C6771EE592D93ULL), 53U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterG) + 0xF4E96F382CF9D311ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterH) ^ 0x811732EF8B6059F9ULL;
