            //
            aOrbiterF = ((aOrbiterF + aOrbiterI) + 0xBB76F8E05CC45842ULL) + aKeySpawnOrbiterUpdateSaltD[((aIndex + 21U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterF) ^ 0xAEB4E7CFA6152A9DULL;
            aOrbiterK = RotL64((aOrbiterK * 0x20EBBF1C38F440C9ULL), 13U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterF) + 0x5C05AF82E378D361ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterC) ^ 0xD6F836F1D8889EC7ULL;
            aOrbiterE = RotL64((aOrbiterE * 0xB41C58D5E54CB913ULL), 47U);
