            aOrbiterK = (aOrbiterK + aOrbiterJ) + 0x14D121F1579B1A82ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterK) ^ 0x0EE221355539B9BAULL;
            aOrbiterB = RotL64((aOrbiterB * 0x836EE76BA85DD4E7ULL), 53U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterC) + 0x7B513708E07F79C9ULL;
